  "F....", // z=12
  ".....", // z=13
  ".j...", // z=14
  "F....", // z=15
  ".....", // z=16
  ".S...", // z=17
];
// y=3: crown
const Y3 = [
  ".....", // z=12
  "JJJ..", // z=13
  "JJJ..", // z=14
  "JJJ..", // z=15
  ".....", // z=16
  ".....", // z=17
];
// y=4: crown top
