  ".....", // z=12
  ".J...", // z=13
  "JJJ..", // z=14
  ".J...", // z=15
  ".....", // z=16
  ".....", // z=17
];

export function build(g) {
  layers(g, [17, 1, 12], LEGEND, [Y1, Y2, Y3, Y4]);
}

